parameters.jsCode:
const trigger = $("Incoming Message Trigger").first().json;

// Current node data (Text Only / Audio Prompt / Image + Text)
const current = $input.first().json;

return [
  {
    json: {
      phone: trigger.contacts?.[0]?.wa_id || trigger.messages?.[0]?.from || "",
      profile_name: trigger.contacts?.[0]?.profile?.name || "",
      message: current.question || "",
      message_type: trigger.messages?.[0]?.type || "text",
      timestamp: trigger.messages?.[0]?.timestamp || ""
    }
  }
];

const data = $getWorkflowStaticData('node');

if (data.retryCount === undefined) {
  data.retryCount = 0;
}

data.retryCount++;

return {
  json: {
    ...$json,
    retry_count: data.retryCount
  }
};

